  embedding_model_id STRING NOT NULL COMMENT 'Embedding model as provider/name@version:dims. The model is the namespace of every vector it produced; two models never share an index.',
  vector ARRAY<FLOAT> NOT NULL COMMENT 'The embedding, float32. 1,024 dims x 4 bytes = 4 KB per row.',
  dims BIGINT NOT NULL COMMENT 'Length of vector; must equal the model id\'s dims.',
  job_id STRING NOT NULL COMMENT 'The embedding job that wrote the row.',
  tokens_in BIGINT NOT NULL COMMENT 'Input tokens charged for this row.',
  tokens_out BIGINT NOT NULL COMMENT 'Output tokens charged for this row.',
  cost_usd DOUBLE NOT NULL COMMENT 'Cost in USD at the price in force when the row was written.'
)
